package bidi

import (
	"strings"
	"testing"
)

// transformGoldenFile holds AS400BidiTransform vectors recorded from the JTOpen
// implementation, generated by gen/OrderGolden.java (mode "transform"). The Java
// side runs the call sequence of ConvTableBidiMap (after the table mapping), and the
// generator checks that sequence against the real ConvTableBidiMap for every CCSID
// that has a table class.
//
// Line format, tab separated:
//
//	id, dir (J = ToLogical, A = ToHost), ccsid, stringType, impToImp, numericRoundTrip,
//	removeMarksOnImplicitToVisual, inHex, outHex
//
// outHex is the complete returned data array, its length included.
const transformGoldenFile = "testdata/transform_golden.txt.gz"

func TestTransformGolden(t *testing.T) {
	sc, closeFn := openGolden(t, transformGoldenFile)
	defer closeFn()

	total, changed, jcount, acount := 0, 0, 0, 0
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Split(line, "\t")
		if len(fields) != 9 {
			t.Fatalf("vector %d: want 9 fields, got %d", total, len(fields))
		}
		id, dir, ccsidS, stS, impl, num, rm, inHex, outHex := fields[0], fields[1], fields[2], fields[3],
			fields[4], fields[5], fields[6], fields[7], fields[8]

		ccsid := atoiChecked(t, ccsidS)
		props := Properties{
			StringType:                    atoiChecked(t, stS),
			NoImplicitReordering:          impl == "0",
			NumericOrderingRoundTrip:      num == "1",
			RemoveMarksOnImplicitToVisual: rm == "1",
		}
		in := decodeUnits(t, inHex)

		var got []uint16
		switch dir {
		case "J":
			got = ToLogical(in, ccsid, props)
			jcount++
		case "A":
			got = ToHost(in, ccsid, props)
			acount++
		default:
			t.Fatalf("vector %s: bad direction %q", id, dir)
		}
		if g := encodeUnits(got); g != outHex {
			t.Errorf("vector %s (%s ccsid %d type %d impl %s num %s rm %s)\n input %s\n  got %s\n want %s",
				id, dir, ccsid, props.StringType, impl, num, rm, inHex, g, outHex)
		}
		if outHex != inHex {
			changed++
		}
		total++
	}
	if err := sc.Err(); err != nil {
		t.Fatalf("reading golden file: %v", err)
	}
	if total < 10000 {
		t.Fatalf("only %d golden vectors, expected at least 10000", total)
	}
	if changed < total/10 {
		t.Errorf("only %d of %d vectors changed the text; the vectors look degenerate", changed, total)
	}
	t.Logf("transform golden vectors: %d (J %d, A %d, changed text: %d)", total, jcount, acount, changed)
}

// The string type of a CCSID comes from the table generated from AS400BidiTransform.CCSID_TABLE.
func TestStringTypeForCCSID(t *testing.T) {
	for _, row := range ccsidTable {
		if got := StringTypeForCCSID(row[0]); got != row[1] {
			t.Errorf("ccsid %d: got string type %d, want %d", row[0], got, row[1])
		}
	}
	for _, ccsid := range []int{0, 37, 500, 99999} {
		if got := StringTypeForCCSID(ccsid); got != 0 {
			t.Errorf("non-bidi ccsid %d: got string type %d, want 0", ccsid, got)
		}
	}
}

// The default properties must be the JTOpen defaults: default string type, implicit
// reordering on, no other option.
func TestDefaultProperties(t *testing.T) {
	p := DefaultProperties()
	if p.StringType != StringTypeDefault || p.NoImplicitReordering || p.NumericOrderingRoundTrip ||
		p.WinCompatible || p.InsertMarkers || p.RemoveMarkers || p.RemoveMarksOnImplicitToVisual ||
		p.WordBreak || p.NumeralShaping != NumeralShapingDefault || p.ExpandLamAlef {
		t.Fatalf("unexpected defaults: %+v", p)
	}
}

// StringTypeNone returns the text unchanged, as ConvTableBidiMap does.
func TestToLogicalNone(t *testing.T) {
	in := []uint16{0x05D0, 0x0031, 0x0020}
	p := DefaultProperties()
	p.StringType = StringTypeNone
	got := ToLogical(in, 420, p)
	if encodeUnits(got) != encodeUnits(in) {
		t.Fatalf("NONE changed the text: %s", encodeUnits(got))
	}
}
